  function isoDate(d){const x=new Date(d);x.setMinutes(x.getMinutes()-x.getTimezoneOffset());return x.toISOString().slice(0,10)}
  function summaryDate(){const y=Number($('installationSummaryYear')?.value),m=Number($('installationSummaryMonth')?.value),d=Number($('installationSummaryDay')?.value);if(!y||!m||!d)return isoDate(new Date());return `${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
  function updateSummaryDayNav(){const selected=summaryDate(),today=new Date(),previous=new Date(today),next=new Date(today);previous.setDate(today.getDate()-1);next.setDate(today.getDate()+1);const targets={installationSummaryPreviousDay:isoDate(previous),installationSummaryToday:isoDate(today),installationSummaryNextDay:isoDate(next)};Object.entries(targets).forEach(([id,date])=>{const btn=$(id);if(!btn)return;const active=selected===date;btn.classList.toggle('is-active',active);btn.classList.toggle('primary-btn',active);btn.classList.toggle('secondary-btn',!active);btn.setAttribute('aria-pressed',String(active))})}
  function setSummaryDate(value){const x=new Date(`${value}T12:00:00`),year=$('installationSummaryYear'),month=$('installationSummaryMonth'),day=$('installationSummaryDay');if(!year||!month||!day)return;year.value=String(x.getFullYear());month.value=String(x.getMonth()+1);fillSummaryDays();day.value=String(x.getDate());updateSummaryDayNav()}
  function fillSummaryDays(){const y=Number($('installationSummaryYear')?.value)||new Date().getFullYear(),m=Number($('installationSummaryMonth')?.value)||new Date().getMonth()+1,el=$('installationSummaryDay'),current=Number(el?.value)||1,count=new Date(y,m,0).getDate();if(el){el.innerHTML=Array.from({length:count},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('');el.value=String(Math.min(current,count))}}
  function initSummaryDateFilters(){const now=new Date(),year=$('installationSummaryYear'),month=$('installationSummaryMonth');if(!year||year.options.length)return;year.innerHTML=Array.from({length:7},(_,i)=>now.getFullYear()-3+i).map(y=>`<option value="${y}">${y}</option>`).join('');month.innerHTML=Array.from({length:12},(_,i)=>`<option value="${i+1}">${new Intl.DateTimeFormat('ar-EG-u-nu-latn',{month:'long'}).format(new Date(2026,i,1))}</option>`).join('');setSummaryDate(isoDate(now))}
  function renderSummaryTeamOptions(){const host=$('installationSummaryTeamsOptions');if(!host)return;host.innerHTML=state.summaryTeams.map(t=>`<label class="installation-summary-team-option"><input type="checkbox" value="${esc(t.id)}" ${state.summarySelectedTeams.has(String(t.id))?'checked':''}><span title="${esc(t.name)}">${esc(t.name)}</span></label>`).join('');updateSummaryTeamButton()}
  function updateSummaryTeamButton(){const btn=$('installationSummaryTeamsButton');if(!btn)return;const count=state.summarySelectedTeams.size,total=state.summaryTeams.length;btn.textContent=count===total?'كل الفرق':count?`${count} فرق مختارة`:'لا توجد فرق مختارة'}
  function fillSummarySelectors(data){const rep=$('installationSummaryRepresentative'),current=rep?.value||'';if(rep){rep.innerHTML='<option value="">كل المندوبين</option>'+data.representatives.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');rep.value=current}const incoming=data.teams||[],allowed=new Set(incoming.map(x=>String(x.id)));state.summaryTeams=incoming;if(!state.summaryTeamsInitialized){state.summarySelectedTeams=new Set(incoming.map(x=>String(x.id)));state.summaryTeamsInitialized=true}else{state.summarySelectedTeams=new Set([...state.summarySelectedTeams].filter(x=>allowed.has(x)))}renderSummaryTeamOptions()}
  async function loadInstallationSummary(){updateSummaryDayNav();const box=$('installationSummaryStatus');status(box,'جاري إعداد ملخص المواعيد...');try{const allTeamIds=new Set(state.summaryTeams.map(x=>String(x.id))),explicitTeamFilter=state.summaryTeamsInitialized&&state.summarySelectedTeams.size!==allTeamIds.size,range=summaryMonthRange(),base={representativeId:$('installationSummaryRepresentative')?.value||'',teamIds:[...state.summarySelectedTeams],teamFilterApplied:explicitTeamFilter};const [data,monthly]=await Promise.all([window.InstallationsServiceSafe.installationSummaryReport({...base,date:summaryDate()}),window.InstallationsServiceSafe.installationSummaryReport({...base,dateFrom:range.dateFrom,dateTo:range.dateTo})]);state.summaryData=data;state.summaryMonthlyData=monthly;fillSummarySelectors(data);renderInstallationSummary(data,monthly);status(box,window.InstallationsService?.getReadStatusMessage?.('summaryReport')||'')}catch(e){status(box,e.message||'تعذر إعداد ملخص المواعيد.','error')}}
  function summaryStageTime(v){if(!v)return'—';try{return new Date(v).toLocaleTimeString('ar-SA-u-ca-gregory-nu-latn',{hour:'numeric',minute:'2-digit'})}catch{return'—'}}
  function summaryDuration(a,b){if(!a||!b)return'';const delta=new Date(b)-new Date(a);if(!Number.isFinite(delta)||delta<0)return'';const mins=Math.round(delta/60000);if(mins<60)return`${mins} دقيقة`;const h=Math.floor(mins/60),m=mins%60;return m?`${h} ساعة و${m} دقيقة`:`${h} ساعة`}
  function summaryTimeline(order){const stages=[['بدء التحرك',order.onRouteAt],['فتح موقع العميل',order.mapOpenedAt],['وصل الموقع',order.arrivedAt],['بدء الموعد',order.startedAt],['التحصيل',order.collectionAt],['تم الانتهاء',order.completedAt]];let reached=-1;stages.forEach((x,i)=>{if(x[1])reached=i});return `<div class="installation-summary-order-timeline">${stages.map((stage,i)=>{const done=Boolean(stage[1]),current=!order.completedAt&&i===reached+1;const duration=i<stages.length-1?summaryDuration(stage[1],stages[i+1][1]):'';return `<div class="installation-summary-stage ${done?'is-done':''} ${current?'is-current':''}">${duration?`<span class="installation-summary-stage-duration">${esc(duration)}</span>`:''}<span class="installation-summary-stage-dot" aria-hidden="true"></span><strong>${esc(stage[0])}</strong><time>${summaryStageTime(stage[1])}</time></div>`}).join('')}</div>`}
  function renderSummaryExecution(data){const host=$('installationSummaryExecutionGroups'),count=$('installationSummaryExecutionCount');if(!host)return;const groups=data.executionGroups||[],total=groups.reduce((a,g)=>a+(g.orders?.length||0),0);if(count)count.textContent=`${num(total)} طلب`;if(!total){host.innerHTML='<div class="installation-summary-execution-empty">لا توجد طلبات تنفيذ ضمن التاريخ والفلاتر المحددة.</div>';return}host.innerHTML=groups.map(group=>`<section class="installation-summary-execution-team"><header><h4>${esc(group.name)}</h4><span>${num(group.orders.length)} طلب</span></header><div class="installation-summary-execution-orders">${group.orders.map(order=>{const services=(order.services||[]).map(x=>`${esc(x.name)} × ${num(x.quantity)}`).join('، ')||'لا توجد خدمات مسجلة';const stateLabel=order.completedAt?'مكتمل':order.startedAt||order.arrivedAt||order.onRouteAt?'قيد التنفيذ':'لم يبدأ';return `<article class="installation-summary-execution-order"><div class="installation-summary-order-meta"><strong>${esc(order.executionNumber||order.requestNumber||'طلب بدون رقم')}</strong><span>${esc(order.customerName||'عميل غير محدد')}</span><span>${esc(order.technicianName||'فني غير محدد')}</span><span>${esc(order.scheduledTime||'وقت غير محدد')}</span><span class="installation-summary-order-state ${order.completedAt?'is-complete':order.startedAt||order.arrivedAt||order.onRouteAt?'is-progress':'is-pending'}">${stateLabel}</span></div><div class="installation-summary-order-services"><span>${services}</span><strong class="installation-summary-order-value">قيمة الطلب = ${summaryMoney(summaryOrderValue(order))}</strong><strong class="installation-summary-order-duration">${esc(summaryExecutionDurationLabel(order))}</strong></div>${summaryTimeline(order)}</article>`}).join('')}</div></section>`).join('')}
