  function kpi(label,value,cls=''){return `<div class="pr-kpi ${cls}"><span>${esc(label)}</span><strong>${value}</strong></div>`}
  function paymentTable(summary,methodRows){const methods=Array.isArray(methodRows)?methodRows:summary.methods;const rows=methods.length?methods.map(x=>`<tr><td>${esc(x.name)}</td><td>${num(x.count)}</td><td class="pr-money">${summaryMoney(x.amount)}</td><td>${summary.collected?Math.round(x.amount/summary.collected*1000)/10:0}%</td></tr>`).join(''):`<tr><td colspan="4">لا توجد عمليات تحصيل مسجلة</td></tr>`;return `<table class="pr-table"><thead><tr><th>طريقة الدفع</th><th>عدد العمليات</th><th>إجمالي المبلغ</th><th>النسبة من المحصل</th></tr></thead><tbody>${rows}</tbody></table>`}
  function serviceTable(rows){return `<table class="pr-table pr-services-table"><thead><tr><th>الخدمة</th><th>عدد الخدمات المنفذة</th><th>إيراد الخدمة شامل الضريبة</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${num(x.quantity)}</td><td class="pr-money">${summaryMoney(x.value)}</td></tr>`).join(''):`<tr><td colspan="3">لا توجد خدمات منفذة</td></tr>`}</tbody></table>`}
  function orderTimeline(order){const stages=[['بدء التحرك',order.onRouteAt],['فتح موقع العميل',order.mapOpenedAt],['وصل الموقع',order.arrivedAt],['بدء الموعد',order.startedAt],['التحصيل',order.collectionAt],['تم الانتهاء',order.completedAt]];return `<div class="pr-timeline">${stages.map((s,i)=>{const next=stages[i+1],duration=next?summaryDuration(s[1],next[1]):'';return `<div class="pr-stage ${s[1]?'done':''}">${duration?`<em>${esc(duration)}</em>`:''}<i></i><b>${esc(s[0])}</b><span>${esc(summaryStageTime(s[1]))}</span></div>`}).join('')}</div>`}
  function compactOrderRow(order){const services=(order.services||[]).map(x=>`${esc(x.name)} × ${num(x.quantity)}`).join('، ')||'لا توجد خدمات مسجلة';return `<article class="pr-order-row"><div class="pr-order-meta-compact"><strong>${esc(order.executionNumber||order.requestNumber||'طلب بدون رقم')}</strong><span>${esc(order.customerName||'عميل غير محدد')}</span><span>${esc(order.technicianName||'فني غير محدد')}</span><span>${esc(order.scheduledTime||'وقت غير محدد')}</span><b class="pr-order-status ${order.completedAt?'done':order.onRouteAt||order.arrivedAt||order.startedAt?'progress':'pending'}">${esc(summaryReportStatus(order))}</b></div><div class="pr-order-services-compact"><span>${services}</span><strong>قيمة الطلب = ${summaryMoney(summaryOrderValue(order))}</strong><strong>${esc(summaryExecutionDurationLabel(order))}</strong></div><div class="pr-order-timeline-compact">${orderTimeline(order)}</div></article>`}
  function chunkRows(rows,size=5){const out=[];for(let i=0;i<rows.length;i+=size)out.push(rows.slice(i,i+size));return out}
